"use strict";(self.webpackChunkfansite_reol=self.webpackChunkfansite_reol||[]).push([[149],{76352:function(e,o,t){t.r(o),t.d(o,{axisLabels:function(){return l},reolTypes:function(){return m},typeGroups:function(){return i}});const i={FG:{code:"FG",name:"突撃型",emoji:"🔥🎸",description:"最前列を愛し、激しい曲に身を委ねるグループ"},FE:{code:"FE",name:"感動型",emoji:"🔥🎹",description:"最前列でエモい曲に心を打たれるグループ"},BG:{code:"BG",name:"俯瞰型",emoji:"🌊🎸",description:"後方からゴリゴリな曲を味わうグループ"},BE:{code:"BE",name:"内観型",emoji:"🌊🎹",description:"後方でエモい曲に浸るグループ"}},l={FB:{left:{key:"F",label:"最前突撃",emoji:"🔥"},right:{key:"B",label:"後方俯瞰",emoji:"🌊"},name:"ライブスタイル"},GE:{left:{key:"G",label:"ゴリゴリ",emoji:"🎸"},right:{key:"E",label:"エモ・バラード",emoji:"🎹"},name:"楽曲の好み"},SQ:{left:{key:"S",label:"布教",emoji:"📢"},right:{key:"Q",label:"没入",emoji:"🎧"},name:"ファン活動"},AI:{left:{key:"A",label:"考察",emoji:"🔍"},right:{key:"I",label:"直感",emoji:"💫"},name:"沼り方"}},m={FGSA:{code:"FGSA",group:"FG",name:"扇動者",song:"煽げや尊し",songLabel:"煽げや尊し型",quote:"衝動的で無敵　いい感じじゃん",emoji:"🪭",color:"#E63946",summary:"最前列で全力で盛り上がりながら、その経験を言語化して周囲にReolの魅力を広めます。考察と布教を両立する、Reolファン界のカリスマ的存在。",sections:[{title:"戦略的な熱狂",body:"単に暴れるだけではなく、ライブ中の体験を言葉にする能力に長けています。「あの曲のあの瞬間、照明が赤に変わった時の会場の熱量がすごかった」と、具体的かつ説得力のある言葉で感動を伝えます。"},{title:"ライブという名の布教活動",body:"ライブは個人的な体験であると同時に布教の素材でもあります。ライブ後にはSNSで長文レポを書き、音源とライブの違いを考察し、初参戦の友人に「次はここに注目して」とアドバイスを送ります。"},{title:"同志を見つける喜び",body:"同じ熱量で語り合える同志を見つけたときの喜びは格別です。「あなたのレポを読んで行ってみた」と言われたときの達成感は、最前列の興奮にも匹敵します。"}],compatibility:{bestMatch:"FGSI",inspire:"BGSA",complement:"BEQI"}},FGSI:{code:"FGSI",group:"FG",name:"鼓舞者",song:"たい",songLabel:"たい型",quote:"もっと馬鹿になりたい　いっしょ、いっしょ",emoji:"⚡",color:"#FF6B35",summary:"最前列で本能のまま暴れ、その熱量で周囲を巻き込んでいくタイプ。「とりあえず一回ライブ来て」が最強の布教スタイル。",sections:[{title:"衝動が生む連鎖反応",body:"行動原理はシンプル。「やりたいからやる」。ライブが始まれば考える前に身体が動き、その圧倒的な熱量が周囲にも伝染していきます。存在そのもので人を動かします。"},{title:"本能の布教者",body:"布教スタイルは論理ではなく体験の共有です。一緒にライブに行って隣で暴れることが最大の布教活動。理屈ではなく「空気」で伝えるのが真骨頂。"},{title:"「やりたい」の純粋さ",body:"打算や計算なく「やりたいからやる」を貫くことで、周囲に安心感を与えます。気づけばその周りにはいつも人が集まっています。"}],compatibility:{bestMatch:"FGSA",inspire:"FGQI",complement:"BEQA"}},FGQA:{code:"FGQA",group:"FG",name:"猛者",song:"生命線",songLabel:"生命線型",quote:"誰も気付かないような感覚を　独り占めしていくのさ",emoji:"💪",color:"#B5179E",summary:"最前列で激しい曲に身を委ねながら、楽曲の構造や音作りを冷静に分析。没入と分析の二重構造を持つ孤高のリスナー。",sections:[{title:"没入と分析の両立",body:"最前列でヘッドバンギングしながら、同時に「あのシンセの音色が前回のライブと違う」と気づける耳を持っています。身体は完全に没入しているのに、脳の一部は冷静に分析を続けています。"},{title:"孤高のリスナー",body:"布教に興味がなく、ライブ後にSNSで感想を書くこともほとんどありません。しかし音楽理論の話題を振れば、驚くほど深い知見を惜しみなく語ってくれるでしょう。"},{title:"命を懸ける覚悟",body:"最前列でなければ得られない情報——アーティストの息遣い、モニタースピーカーから漏れる音——を逃したくないという覚悟が、彼らを最前列に立たせ続けます。"}],compatibility:{bestMatch:"BGQA",inspire:"FGSA",complement:"FESI"}},FGQI:{code:"FGQI",group:"FG",name:"闘士",song:"第六感",songLabel:"第六感型",quote:"今最高潮なんです！第六感、六感またがって　このまま何処までいけるの",emoji:"🥊",color:"#D62828",summary:"理屈抜きで最前列に立ち、本能のままに激しい曲と一体化するタイプ。ライブは「身体で受け止める」もの。",sections:[{title:"身体が先に動く",body:"イントロが鳴った瞬間、考える前に身体が反応しています。なぜその曲が好きなのか聞かれても「わからない、でもヤバい」としか答えられない——でも、それでいい。"},{title:"言葉のいらない世界",body:"ライブ後も「良かった」以上の言葉はなかなか出てきません。でも、言葉にした瞬間に失われるものがあると本能的に知っています。"},{title:"最前列の孤独と充実",body:"余計な気遣いをせずに音楽と一体化できる一人参戦を好む傾向があります。汗だくで会場を出るときの充実感は、闘士にしかわからない特別なもの。"}],compatibility:{bestMatch:"BGQI",inspire:"FGSI",complement:"BESA"}},FESA:{code:"FESA",group:"FE",name:"伝承者",song:"宵々古今",songLabel:"宵々古今型",quote:"移ろうは古今　航路なら堂々　恐るることなどはあらざらむ",emoji:"📜",color:"#7B2D8E",summary:"最前列で受けた感動を深く考察し、その体験を丁寧に言語化して伝えます。一つひとつのライブを「歴史」として記録する語り手。",sections:[{title:"感動を「歴史」にする人",body:"一つひとつのライブ体験を「記録すべき歴史」として捉えています。過去のライブや楽曲のリリース時期と結びつけ、文脈の中に位置づけます。"},{title:"布教のための分析",body:"長文のライブレポはもちろん、過去のセットリストとの比較表を作ったり、演出の変遷をまとめたりと、体系的で資料性に富んだ伝え方をします。"},{title:"過去と未来を繋ぐ橋",body:"伝承者のレポや感想には独特の深みと温かみがあり、読む人に「自分もReolの歴史の一部なんだ」と感じさせる力があります。"}],compatibility:{bestMatch:"FESI",inspire:"BESA",complement:"FGQA"}},FESI:{code:"FESI",group:"FE",name:"語り部",song:"サイサキ",songLabel:"サイサキ型",quote:"足掻いても伝わらないよそれでも僕らには言葉しかないから　歌い続けるよ",emoji:"🎤",color:"#E76F51",summary:"最前列で直感的に受け取った感動を、そのまま熱く周囲に語るタイプ。感情の鮮度を大切にする天性の共感力の持ち主。",sections:[{title:"感情の翻訳者",body:"「あの瞬間、マジで泣いた」「照明が変わった瞬間に鳥肌が立った」という素直な感情表現が、読む人の共感を呼びます。言葉はストレートで飾り気がないけれど、だからこそ心に真っ直ぐ届きます。"},{title:"共感の連鎖",body:"感想を発信すると「わかる！」というリプライが連なり、気づけばTLが同じライブの感動で溢れている——そんな光景を生み出します。"},{title:"「響かせる」ということ",body:"意図して布教しているわけではありません。ただ感じたことを素直に発信しているだけですが、その感情の純度が高いからこそ、結果として最も効果的な布教になっています。"}],compatibility:{bestMatch:"FESA",inspire:"BESI",complement:"BGQA"}},FEQA:{code:"FEQA",group:"FE",name:"探究者",song:"ミュータント",songLabel:"ミュータント型",quote:"答を、アウフガーベ　迷いを正して",emoji:"🔬",color:"#457B9D",summary:"最前列でエモい曲に浸りながら、歌詞やMVの深い意味を一人で探り続けます。独自の解釈で音楽の深淵に潜る孤独な探究者。",sections:[{title:"独自の進化を遂げた存在",body:"既存の解釈に満足できず、自分だけの答えを見つけ出すために歌詞を何度も読み返し、MVのワンカットを何十回も再生します。"},{title:"孤独な探究の道",body:"自分の考察を積極的に共有しません。まだ探究の途中だから。中途半端な解釈を発信することを嫌い、腑に落ちるまで考え続けます。"},{title:"変異し続ける感性",body:"同じ曲を半年後に聴いたとき、まったく違う意味を見出すことがあります。音楽と自分の関係が常に「突然変異」し続けていることを楽しめるのが強みです。"}],compatibility:{bestMatch:"BEQA",inspire:"FEQI",complement:"BGSI"}},FEQI:{code:"FEQI",group:"FE",name:"詩人",song:"1LDK",songLabel:"1LDK型",quote:"イヤフォンの向こうへ　三分と少しの間だけ　全能感、革命的な気分でいさせて",emoji:"🪶",color:"#264653",summary:"最前列で繊細に音楽を受け止め、言葉にならない余韻をそっと心に留めます。音楽との一対一の対話を大切にする静かな感受性の持ち主。",sections:[{title:"一対一の対話",body:"ライブは大勢の中にいながらReolと一対一で向き合う時間。会場の喧騒の中に自分だけの静かな空間を作り出します。声の息遣い、ピアノの残響を一つも逃したくない。"},{title:"言葉にしない美学",body:"ライブの感想をほとんど発信しません。言葉にした瞬間に何かが失われると直感的に感じているから。帰りの電車で余韻に浸る時間が最も大切。"},{title:"繊細さという強さ",body:"他の人が気づかないような微細な変化——MCのニュアンスの違い、セットリストの並びが生む感情の流れ——に気づき、静かに心に刻んでいます。"}],compatibility:{bestMatch:"BEQI",inspire:"FEQA",complement:"BGSA"}},BGSA:{code:"BGSA",group:"BG",name:"軍師",song:"ウテナ",songLabel:"ウテナ型",quote:"あなたと機械になって　御眼鏡通りさ　浮かぶ理想郷",emoji:"♟️",color:"#2A9D8F",summary:"後方から全体を見渡して冷静に分析し、その知見を戦略的に共有します。会場レポや音響分析など実用的な情報を体系的にまとめる参謀。",sections:[{title:"凛とした知略家",body:"最前列の熱狂を冷静に観察し、会場全体の空気感、照明と音響の連携、観客の反応のうねりをマクロな視点で捉えます。後方に立つのは全体像を把握するための戦略的なポジショニングです。"},{title:"知見の戦略的共有",body:"会場ごとの音響の違い、座席位置と見え方の関係、効率的な物販攻略法——実用的な情報を体系的にまとめ上げることが得意です。"},{title:"冷静さの中の情熱",body:"冷静に見えますが内側にはReolへの深い情熱が。感情的な言葉ではなく、精緻な分析と有用な情報提供という形で愛情を示します。"}],compatibility:{bestMatch:"BGSI",inspire:"FGSA",complement:"FEQI"}},BGSI:{code:"BGSI",group:"BG",name:"賢者",song:"Q?",songLabel:"Q?型",quote:"生きるほど傷が増えていく　それでも探している僕らの理由を",emoji:"🦉",color:"#588157",summary:"後方から直感的に場の空気を読み取り、独自の問いかけで周囲に気づきを与えます。謎めいた洞察力を持つ不思議な存在。",sections:[{title:"問いを投げる人",body:"分析的な答えを出すのではなく、直感的な「問い」を投げかけます。「あの曲、なんであのタイミングで演ったんだろう？」——その問いが周囲の思考を刺激します。"},{title:"空気を読む達人",body:"後方から会場全体の空気を直感的に感じ取ります。論理的な根拠はないけれど、なぜか的を射た観察をするのが特徴です。"},{title:"謎めいた存在感",body:"ぽつりと投げる一言が周囲に長い余韻を残します。答えを押し付けるのではなく問いを共有するスタンスが、心地よい知的刺激を与えています。"}],compatibility:{bestMatch:"BGSA",inspire:"BGQI",complement:"FGQA"}},BGQA:{code:"BGQA",group:"BG",name:"観測者",song:"ちるちる",songLabel:"ちるちる型",quote:"知れば知るほど苦しい　それでもなぜ、知りたいの",emoji:"📊",color:"#344E41",summary:"後方から冷静にライブを観測し、論理的に詳細な記録と分析を重ねます。16タイプの中で最も客観的にライブを「観る」存在。",sections:[{title:"論理の代理人",body:"感情を排したピュアなデータでライブを記録し分析します。セットリストの順番、曲間の秒数、照明の色彩パターン——あらゆる情報を脳内データベースに記録し続けています。"},{title:"感情を排した純粋な分析",body:"「良かった」ではなく「前回のツアーと比べてMCの長さが平均20秒伸びている」といった客観的事実の積み重ねを好みます。感情の排除は、音楽への最大の敬意です。"},{title:"孤高の記録者",body:"分析を積極的に共有しません。記録ノートにはファンの誰よりも詳細なライブの記録が残されていますが、それは自分のためのものです。"}],compatibility:{bestMatch:"FGQA",inspire:"BGSA",complement:"FESI"}},BGQI:{code:"BGQI",group:"BG",name:"共鳴者",song:"激白",songLabel:"激白型",quote:"間違っていても　痛い思いをしても構わないよ　不幸も君とだけ",emoji:"🌋",color:"#6D597A",summary:"後方で直感的にライブの空気と共鳴し、内なる衝動と静かに向き合います。外見は静かでも、内面は激しく燃えている存在。",sections:[{title:"激しくも純粋な共鳴",body:"外見からは想像できないほど内面は激しく動いています。身体ではなく内面で「暴れる」のです。ベースラインが身体を震わせ、ドラムが心臓の鼓動と重なるとき、完全な一体感を体験します。"},{title:"後方という選択",body:"音楽と内面的に共鳴するためには物理的な距離が必要。後方で目を閉じて音に身を委ねるとき、音楽は外からの刺激ではなく、自分の内側から湧き上がるものになります。"},{title:"言葉にならない、だからいい",body:"感じすぎているからこそ語ることが苦手。あの瞬間の高揚を「良かった」で片付けることへの抵抗が、共鳴者を沈黙させます。"}],compatibility:{bestMatch:"FGQI",inspire:"BGSI",complement:"FESA"}},BESA:{code:"BESA",group:"BE",name:"伝道者",song:"シンカロン",songLabel:"シンカロン型",quote:"僕の指先から送り出す理想　急転直下　不安定な信号をきっと拾ってよ",emoji:"📖",color:"#1D3557",summary:"後方で深く味わった感動を、論理的に整理して多くの人に届けます。温かい論理で「なぜこの曲が心に響くのか」を丁寧に紐解く人。",sections:[{title:"感動の進化を伝える",body:"感動は一度きりの出来事ではなく、ライブを重ねるごとに進化していくもの。「感動の進化」を丁寧に言語化し、時系列で整理して伝えるのが使命です。"},{title:"温かい論理",body:"「なぜこの曲が心に響くのか」を丁寧に紐解き、読む人が自分自身の体験と照らし合わせて共感できるような書き方をします。考察的でありながらも温かみがあるのが特徴。"},{title:"「伝える」ことの責任",body:"何度も推敲を重ねてから発信します。頻度は高くありませんが、一つひとつの投稿には深い愛情と考察が詰まっており、「保存して何度も読み返したくなる」質の高いコンテンツを生み出します。"}],compatibility:{bestMatch:"BESI",inspire:"FESA",complement:"FGQI"}},BESI:{code:"BESI",group:"BE",name:"表現者",song:"極彩色",songLabel:"極彩色型",quote:"この命を彩る色　染める色は　極めて鮮やか",emoji:"🎨",color:"#F72585",summary:"後方で直感的に感じたものを、自分なりの鮮やかな表現で周囲に伝えます。イラスト、詩、ファンアートなど言葉を超えた表現力の持ち主。",sections:[{title:"鮮やかな感性の持ち主",body:"16タイプの中で最も独創的な方法でReolの音楽を表現します。イラストを描いたり、詩に綴ったり——言葉だけに頼らない多彩な表現力を持っています。"},{title:"後方からのインプット",body:"後方にいることで、照明が作り出す会場全体の色彩、観客のシルエットの美しさ、ステージと客席が一体になる瞬間の全景——創作の素材を心に焼き付けます。"},{title:"共有することの喜び",body:"「あのライブ、こんな感じだった」とイラストを一枚投稿するだけで、言葉では伝えきれないライブの空気感を一瞬で伝えてしまう力があります。"}],compatibility:{bestMatch:"BESA",inspire:"FESI",complement:"FGSA"}},BEQA:{code:"BEQA",group:"BE",name:"求道者",song:"un, deux, trois",songLabel:"un, deux, trois型",quote:"あなたの哲学に抱かれたい　今公転する公転する、僕",emoji:"🧭",color:"#023E8A",summary:"後方から一人で音楽の深淵を分析し、理想の音楽体験を探り続けます。感情を論理で解き明かそうとするストイックな探究者。",sections:[{title:"一つずつ、丁寧に",body:"歌詞の一節、メロディの一小節、アレンジの一つの選択——すべてに意味があると信じ、妥協することなく分析を続けます。感情を論理で解き明かそうとする、一見矛盾した試みが本質。"},{title:"終わりなき探究",body:"一つの答えに辿り着いたと思ったら、その先にまた新しい問いが待っています。「なぜReolの音楽はこれほど心を動かすのか」という根源的な問いに、歩みを止めません。"},{title:"静かなる情熱",body:"ライブ後、一人でカフェに入り、ノートを開いて今日の気づきを書き留める——求道者の本当のライブ体験は、会場を出た後から始まるのかもしれません。"}],compatibility:{bestMatch:"FEQA",inspire:"BEQI",complement:"FGSI"}},BEQI:{code:"BEQI",group:"BE",name:"内省者",song:"エンド",songLabel:"エンド型",quote:"僕を好きだと言う君が大嫌い",emoji:"🪞",color:"#4A4E69",summary:"後方で直感的に音楽を受け止め、自分の内面を静かに見つめるタイプ。16タイプの中で最も静かで、最も内面的な存在。",sections:[{title:"最も静かなタイプ",body:"後方の最も人の少ないエリアに立ち、音楽と自分だけの世界に沈む。曲を聴きながら、自分の過去の記憶や感情が浮かんでは消えていく——ライブは「瞑想」に近い体験。"},{title:"音楽という鏡",body:"歌詞の中に自分と重なる感情を見出し、メロディの中に自分の心の揺れを感じます。「この曲は私のための曲だ」という確信がある。"},{title:"共有しないという選択",body:"ライブで感じたことは極めて個人的な体験。ライブ後に一人で帰路につく時間、暗い部屋で余韻に浸る時間こそが、ライブ体験の本質です。"}],compatibility:{bestMatch:"FEQI",inspire:"BEQA",complement:"BGSI"}}}}}]);
//# sourceMappingURL=9d7bd4d99383ffe79797e24971344582c4fa1b16-7da96f6741badd338ea0.js.map